import test from 'node:test';import assert from 'node:assert/strict';import {decodeFunctionData} from '../enclave/node_modules/viem/_esm/index.js';import {OWNER_ABI} from '../enclave/network/lease-gas-owner.mjs';import {depositPlan,APP,RESERVE,OWNER} from './deposit-plan.mjs';
const R='0xcc00efe9c79c17b34ef9edc2720939030834bf168abc52cea14dcb224304a979',L='0x71d50076336283e774ba2ef8d5cbf7602e9cdc5dd918a7e7390c743367766682';
function chain(change={}){return{chainId:8453,snapshot:async()=>({value:{reserveHash:R,ledgerHash:L,id:APP,owner:OWNER,active:true,reserveWei:1350467058005n,enabled:true,balance:2000000000000000n,...change},blockNumber:1n,blockHash:'0x01',agreeing:3,peers:3})}}
test('exact app deposit, no configure or generic ETH transfer',async()=>{const p=depositPlan(1000000000000000n);const v=await p.steps[0].check(chain());assert.equal(v.state,'ready');assert.equal(v.tx.to,RESERVE);assert.equal(v.tx.value,1000000000000000n);const call=decodeFunctionData({abi:OWNER_ABI,data:v.tx.data});assert.equal(call.functionName,'deposit');assert.deepEqual(call.args,[APP]);});
test('wrong code, owner, identity, disabled reserve and insufficient wallet refuse',async()=>{for(const x of [{reserveHash:'wrong'},{ledgerHash:'wrong'},{owner:RESERVE},{id:'0x01'},{active:false},{enabled:false},{balance:0n}]){const v=await depositPlan(1000000000000000n).steps[0].check(chain(x));assert.equal(v.state,'blocked');assert.equal(v.tx,undefined);}});
test('confirmed handoff prevents a second deposit and unreviewed amounts refuse',async()=>{assert.throws(()=>depositPlan(2000000000000000n),/Unreviewed/);const v=await depositPlan(1000000000000000n,{confirmed:()=>true}).steps[0].check(chain());assert.equal(v.state,'done');assert.equal(v.tx,undefined);});
